contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable {
        uint ownerBefore = uint(uint160(c.owner()));
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint ownerAfter = uint(uint160(c.owner()));
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;

        assert(
            ownerAfter == ownerBefore &&
            depositsAfter == depositsBefore &&
            (
                (v > balBefore && reverted && balAfter == balBefore) ||
                (v <= balBefore && !reverted && balAfter == balBefore - v)
            )
        );
    }

    receive() external payable {}
}

